package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BuiltinVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property builtin of observed dashboard ")
  void test_builtin_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> BuiltinVO.tryFrom(null));
    Assertions.assertEquals(true, BuiltinVO.from(true).isBuiltin());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> BuiltinVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", BuiltinVO.from(true).toString());
  }
}
